INSERT INTO `prescricao_atestados_diagnosticos_pedidosexames` (`tipo`, `PacienteId`, `NomePaciente`, `conteudo`, `datahora`, `Usuario_ID`, `profissional`) VALUES 
			('Atestado', '2', 'Maria de exemplo da silva', '***', '2023-10-17 11:20:44', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1678', 'Max Welington Torres Matheus Dias', '<p><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;><strong>Paciente foi avaliado para prescri&ccedil;&atilde;o de palmilha biomec&acirc;nica com o intuito de melhorar o alinhamento do membro inferior e reduzir sobrecarga nas articula&ccedil;&otilde;es do joelho e tornozelo. Ap&oacute;s a avalia&ccedil;&atilde;o sugiro alguns exerc&iacute;cios para potencializar a adapta&ccedil;&atilde;o e a melhora cl&iacute;nica do paciente. Segue abaixo as sugest&otilde;es de exerc&iacute;cios:</strong></span></p>\n\n<p>&nbsp;</p>\n\n<ol>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhorar a mobilidade de quadril, principalmente para ganho de rota&ccedil;&atilde;o medial, mas tamb&eacute;m tentar ganhar um pouco de rota&ccedil;&atilde;o lateral, bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhora da mobilidade do tornozelo, principalmente para ganho de dorsiflex&atilde;o bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento para m&uacute;sculos estabilizadores do tronco, principalmente transverso abdominal.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento de gl&uacute;teo m&aacute;ximo preferencialmente em posi&ccedil;&atilde;o de maior encurtamento deste grupo muscular, evitando fortalecimento em posi&ccedil;&atilde;o alongada.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de m&uacute;sculos roteadores laterais do quadril, principalmente gl&uacute;teo m&eacute;dio, preferencialmente com o quadril em posi&ccedil;&atilde;o neutra ou leve extens&atilde;o, favorecendo o fortalecimento em posi&ccedil;&atilde;o de encurtamento muscular.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento exc&ecirc;ntrico e na posi&ccedil;&atilde;o alongada e m&uacute;sculos flexores plantares, principalmente tr&iacute;ceps sural.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de quadr&iacute;ceps bilateral em CCA e CCF iniciando com a ADM livre de dor e evoluindo para amplitudes maiores de movimento.</span></li>\n</ol>\n<span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Qualquer d&uacute;vida com rela&ccedil;&atilde;o aos exerc&iacute;cios me encontro &agrave; disposi&ccedil;&atilde;o para quaisquer esclarecimento pelo telefone abaixo</span>\n\n<div style=&quot;text-align: center;&quot;><br />\n<span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Warley de Melo Oliveira<br />\nCREFITO 4/64832-F<br />\n(31) 99185-6084</span></div>\n', '2023-11-23 13:32:42', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1678', 'Max Welington Torres Matheus Dias', '<p><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;><strong>Paciente foi avaliado para prescri&ccedil;&atilde;o de palmilha biomec&acirc;nica com o intuito de melhorar o alinhamento do membro inferior e reduzir sobrecarga nas articula&ccedil;&otilde;es do joelho e tornozelo. Ap&oacute;s a avalia&ccedil;&atilde;o sugiro alguns exerc&iacute;cios para potencializar a adapta&ccedil;&atilde;o e a melhora cl&iacute;nica do paciente. Segue abaixo as sugest&otilde;es de exerc&iacute;cios:</strong></span></p>\n\n<p>&nbsp;</p>\n\n<ol>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhorar a mobilidade de quadril, principalmente para ganho de rota&ccedil;&atilde;o medial, mas tamb&eacute;m tentar ganhar um pouco de rota&ccedil;&atilde;o lateral, bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhora da mobilidade do tornozelo, principalmente para ganho de dorsiflex&atilde;o bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento para m&uacute;sculos estabilizadores do tronco, principalmente transverso abdominal.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento de gl&uacute;teo m&aacute;ximo preferencialmente em posi&ccedil;&atilde;o de maior encurtamento deste grupo muscular, evitando fortalecimento em posi&ccedil;&atilde;o alongada.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de m&uacute;sculos roteadores laterais do quadril, principalmente gl&uacute;teo m&eacute;dio, preferencialmente com o quadril em posi&ccedil;&atilde;o neutra ou leve extens&atilde;o, favorecendo o fortalecimento em posi&ccedil;&atilde;o de encurtamento muscular.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento exc&ecirc;ntrico e na posi&ccedil;&atilde;o alongada e m&uacute;sculos flexores plantares, principalmente tr&iacute;ceps sural.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de quadr&iacute;ceps bilateral em CCA e CCF iniciando com a ADM livre de dor e evoluindo para amplitudes maiores de movimento.</span></li>\n</ol>\n<span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Qualquer d&uacute;vida com rela&ccedil;&atilde;o aos exerc&iacute;cios me encontro &agrave; disposi&ccedil;&atilde;o para quaisquer esclarecimento pelo telefone abaixo</span>\n\n<div style=&quot;text-align: center;&quot;><br />\n<span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>(31) 99185-6084</span></div>\n', '2023-11-23 13:33:04', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1838', 'Felipe Webres Martins', 'Declaro para os devidos fins que o paciente Felipe Webres Martins, 39 anos, portador do documento de identidade número MG-12.148.203, apresenta uma atrofia muscular do músculo tríceps sural esquerdo, com uma limitação de amplitude de movimento do tornozelo da mesma perna. No teste de lunge apresenta 20 graus. de dorsiflexão. &nbsp;Tais alterações resultam na redução funcional do comprimento do membro inferior esquerdo e proporcionam um aumento na pronação temporal e espacial deste membro, com recomendação do uso de palmilhas para correção. Segundo informações colhidas com o paciente estas alterações foram provocadas por uma infeccção pelo vírus varicela-zoster.<br />\n<br />\n&nbsp;', '2024-03-20 16:30:24', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1838', 'Felipe Webres Martins', 'Declaro para os devidos fins que o paciente Felipe Webres Martins, 39 anos, portador do documento de identidade número MG-12.148.203, apresenta uma atrofia muscular do músculo tríceps sural esquerdo, com uma limitação de amplitude de movimento do tornozelo da mesma perna. No teste de lunge apresenta 20 graus. de dorsiflexão. &nbsp;Tais alterações resultam na redução funcional do comprimento do membro inferior esquerdo e proporcionam um aumento na pronação temporal e espacial deste membro, com recomendação do uso de palmilhas para correção. Segundo informações colhidas com o paciente estas alterações foram provocadas por uma infeccção pelo vírus varicela-zoster.<br />\n&nbsp;', '2024-03-20 16:31:59', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1730', 'Vera Lúcia Nogueira', 'Declaro para os devidos fins que a paciente supracitada faz uso de palmilhas ortopédicas biomecânicas, por apresenta quadro de pronação temporal e espacial dos pés o que acarreta em dores em seus membros inferiores e na coluna. A paciente precisa utilizar o dispositivo de maneira initerrupta para melhorar o movimento e posicionamento dos seus pés minimizando assim os sintomas. As palmilhas são confeccionadas sob medida no material EVA (Etilenovinilacetato) e devem ser utilizada no interior do seu calçado diariamente.<br />\n<br />\nQualquer esclarecimento me encontro a disposição pelo número (31) 99185-6084.', '2024-04-04 06:26:38', '160137673', 'Warley de Melo Oliveira'),
			('Atestado', '1678', 'Max Welington Torres Matheus Dias', '<p><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;><strong>Paciente foi avaliado para prescri&ccedil;&atilde;o de palmilha biomec&acirc;nica com o intuito de melhorar o alinhamento do membro inferior e reduzir sobrecarga nas articula&ccedil;&otilde;es do joelho e tornozelo. Ap&oacute;s a avalia&ccedil;&atilde;o sugiro alguns exerc&iacute;cios para potencializar a adapta&ccedil;&atilde;o e a melhora cl&iacute;nica do paciente. Segue abaixo as sugest&otilde;es de exerc&iacute;cios:</strong></span></p>\n\n<p>&nbsp;</p>\n\n<ol>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhorar a mobilidade de quadril, principalmente para ganho de rota&ccedil;&atilde;o medial, mas tamb&eacute;m tentar ganhar um pouco de rota&ccedil;&atilde;o lateral, bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios para melhora da mobilidade do tornozelo, principalmente para ganho de dorsiflex&atilde;o bilateral.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento para m&uacute;sculos estabilizadores do tronco, principalmente transverso abdominal.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Exerc&iacute;cios de fortalecimento de gl&uacute;teo m&aacute;ximo preferencialmente em posi&ccedil;&atilde;o de maior encurtamento deste grupo muscular, evitando fortalecimento em posi&ccedil;&atilde;o alongada.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de m&uacute;sculos roteadores laterais do quadril, principalmente gl&uacute;teo m&eacute;dio, preferencialmente com o quadril em posi&ccedil;&atilde;o neutra ou leve extens&atilde;o, favorecendo o fortalecimento em posi&ccedil;&atilde;o de encurtamento muscular.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento exc&ecirc;ntrico e na posi&ccedil;&atilde;o alongada e m&uacute;sculos flexores plantares, principalmente tr&iacute;ceps sural.</span></li>\n\t<li><span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Fortalecimento de quadr&iacute;ceps bilateral em CCA e CCF iniciando com a ADM livre de dor e evoluindo para amplitudes maiores de movimento.</span></li>\n</ol>\n<span style=&quot;font-family:tahoma,geneva,sans-serif&quot;>Me encontro &agrave; disposi&ccedil;&atilde;o para quaisquer esclarecimento pelo telefone&nbsp;</span><span style=&quot;font-family:tahoma,geneva,sans-serif; text-align:center&quot;>(31)99185-6084.&nbsp;</span>', '2023-11-23 13:33:58', '160137673', 'Warley de Melo Oliveira'),
